<script setup lang="ts">import {ref,computed,watch} from 'vue';import type {Workspace} from '../stores/workspace';import Heading from '../components/common/Heading.vue';import Empty from '../components/common/Empty.vue';import Status from '../components/common/Status.vue';import PolicyStrip from '../components/PolicyStrip.vue';import AreaSummary from '../components/AreaSummary.vue';import SurveyPlot from '../components/SurveyPlot.vue';import GroupTable from '../components/GroupTable.vue';import VertexEvidence from '../components/VertexEvidence.vue';import {short,num,pct} from '../utils/format';const props=defineProps<{data:Workspace;selected:string}>();const id=ref(props.selected||'demo-run'),gid=ref('G01'),tab=ref('plot');watch(()=>props.selected,v=>{if(v)id.value=v});const run=computed(()=>props.data.runs.find(r=>r.id===id.value)||props.data.runs[0]),result=computed(()=>run.value?.status==='completed'?run.value.result:null),group=computed(()=>result.value?.groups.find(g=>g.group_id===gid.value)||result.value?.groups[0]);</script><template><Heading index="05 / GEOMETRY EVIDENCE" title="面积与边界，逐一核对。" detail="全部结果由Python worker计算并持久化。图按真实米制比例绘制，凸包/轴框/定向框面积独立列示。"/><label class="selector">选择包络运行<select aria-label="选择包络运行" v-model="id"><option v-for="r in data.runs" :key="r.id" :value="r.id">{{data.studies.find(s=>s.id===r.study_id)?.name}} · {{r.status}} · {{short(r.id)}}</option></select></label><Empty v-if="!run">先在包络研究任务页运行一次，完成后查看边界、面积与退化类型。</Empty><template v-else><div class="result-meta"><Status :value="run.status"/><span>RUN {{short(run.id)}}</span><span v-if="result">SHA256 {{short(result.checksum)}}</span></div><p v-if="run.status==='queued'||run.status==='running'" role="status" class="notice">后台正在计算凸包及逐边方向包围框，完成后自动刷新。</p><p v-if="run.status==='failed'" role="alert" class="notice error">{{run.error}} · 保留失败记录，调整口径后新建研究重试。</p><template v-if="result&&group"><PolicyStrip :policy="result.policy"/><label class="selector group-selector">结果点组<select aria-label="结果点组" v-model="gid"><option v-for="g in result.groups" :key="g.group_id" :value="g.group_id">{{g.group_id}} {{g.name}} / {{g.hull.geometry_type}}</option></select></label><AreaSummary :group="group"/><div class="tabs"><button :class="{active:tab==='plot'}" @click="tab='plot'">包络比例图</button><button :class="{active:tab==='table'}" @click="tab='table'">面积与退化</button><button :class="{active:tab==='vertices'}" @click="tab='vertices'">边界顶点证据</button></div><section class="evidence-section"><h2>{{tab==='plot'?'三种边界·等比例米制平面':tab==='table'?'完整点组·面积与退化类型':'顶点与全部原始点包含性'}}</h2><template v-if="tab==='plot'"><SurveyPlot :points="group.raw_points" :result="group" :title="group.group_id+' / '+group.name"/><div class="counts-strip"><span>原始 <b>{{group.hull.input_count}}</b></span><span>唯一 <b>{{group.hull.unique_count}}</b></span><span>重复 <b>{{group.hull.duplicate_count}}</b></span><span>几何 <b>{{group.hull.geometry_type}}</b></span></div></template><template v-else-if="tab==='table'"><GroupTable :groups="result.groups"/><p class="muted">凸包或框面积为0时不伪造面；周长仅polygon有值，线另报line_length，point/line周长为null。当前框/凸包比={{group.box_to_hull_ratio===null?'不可估计（分母0）':num(group.box_to_hull_ratio,4)}}；轴框冗余降低={{pct(group.axis_reduction_fraction)}}。</p></template><VertexEvidence v-else :group="group"/></section><details><summary>口径、完整来源计数与解释边界</summary><p>来源{{result.source_group_count}}组；本次选择{{result.selected_group_ids.join(' / ')}}；全源测组仍在研究快照，不因组选择删改。</p><p v-for="s in result.assumptions" :key="s">{{s}}</p><p class="mono">{{result.checksum}}</p></details></template></template></template>